#!/usr/bin/env bash
# Applies חובותיי's customizations to the Android project generated by `npx cap add android`.
set -euo pipefail

RUN="${GITHUB_RUN_NUMBER:-1}"
APP=android/app
RES=$APP/src/main/res

# 1) Icons, notification icon, splash
find "$RES" -name 'splash.png' -delete
cp -R android-res/. "$RES/"

# 2) Permissions for reminders (exact alarms, restore after reboot, notifications, vibration)
MAN=$APP/src/main/AndroidManifest.xml
perl -0pi -e 's|</manifest>|    <uses-permission android:name="android.permission.POST_NOTIFICATIONS" />\n    <uses-permission android:name="android.permission.SCHEDULE_EXACT_ALARM" />\n    <uses-permission android:name="android.permission.USE_EXACT_ALARM" />\n    <uses-permission android:name="android.permission.RECEIVE_BOOT_COMPLETED" />\n    <uses-permission android:name="android.permission.VIBRATE" />\n</manifest>|' "$MAN"

# 3) Splash on Android 12+ in the app color
STY=$RES/values/styles.xml
perl -0pi -e 's|(<style name="AppTheme.NoActionBarLaunch" parent="Theme.SplashScreen">)|$1\n        <item name="windowSplashScreenBackground">#1E5F74</item>\n        <item name="windowSplashScreenAnimatedIcon">\@mipmap/ic_launcher_foreground</item>|' "$STY"

# 4) Target SDK 34 (classic status bar; the app is installed directly, not from Play)
sed -i -E 's/targetSdkVersion = [0-9]+/targetSdkVersion = 34/' android/variables.gradle

# 5) Version from the build number, so every new APK installs as an update over the old one
sed -i -E "s/versionCode [0-9]+/versionCode ${RUN}/; s/versionName \"[^\"]*\"/versionName \"1.0.${RUN}\"/" "$APP/build.gradle"

# 6) Release signing with the permanent key (password from the repo secret)
cat >> "$APP/build.gradle" <<'EOF'

android {
    signingConfigs {
        chovotai {
            storeFile file("release.jks")
            storePassword System.getenv("CHOVOTAI_STORE_PASSWORD")
            keyAlias System.getenv("CHOVOTAI_KEY_ALIAS")
            keyPassword System.getenv("CHOVOTAI_KEY_PASSWORD")
        }
    }
    buildTypes {
        release {
            signingConfig signingConfigs.chovotai
            minifyEnabled false
        }
    }
}
EOF

echo "--- manifest permissions"; grep -n 'uses-permission' "$MAN"
echo "--- launch style"; grep -n -A3 'NoActionBarLaunch' "$STY"
echo "--- versions"; grep -n -E 'versionCode|versionName' "$APP/build.gradle"; grep -n targetSdk android/variables.gradle
